set -euo pipefail
cd /home/ubuntu/apps/travel-planner
.venv/bin/python - <<'PY'
from pathlib import Path
import json,base64,hashlib,shutil
payload=json.loads('{"rag/eval/baselines/plan_v1/manifest.json": "", "rag/eval/baselines/plan_v1/rag/eval/test_plan_service.py": "", "rag/eval/baselines/plan_v1/rag/eval/verify_plan_live.py": "", "rag/eval/baselines/plan_v1/rag/eval/reports/luoyang_one_day_v1_final.json": "", "rag/eval/baselines/plan_v1/rag/eval/reports/luoyang_one_day_v1_final.md": "", "rag/eval/baselines/plan_v1/rag/eval/reports/planning_v1_qa_regression.json": "", "rag/eval/baselines/plan_v1/rag/eval/reports/plan_v1_acceptance.json": "", "rag/eval/baselines/plan_v1/rag/eval/reports/plan_v1_acceptance.md": "", "rag/eval/baselines/plan_v1/rag/service/plan_service.py": "", "rag/eval/candidates/plan_v1/manifest.json": "", "rag/eval/reports/plan_v1_acceptance.json": "", "rag/eval/reports/plan_v1_acceptance.md": "", "docs/PROJECT_STATUS_AND_ARCHITECTURE.md": "", "docs/PLAN_ONE_DAY.md": "", "docs/PROJECT_MEMORY.md": ""}')
for n,b in payload.items():
 p=Path(n); data=base64.b64decode(b)
 if n.startswith('rag/eval/baselines/plan_v1/') and p.exists(): assert p.read_bytes()==data, 'Existing baseline differs: '+n
 p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(data)
 assert hashlib.sha256(p.read_bytes()).hexdigest()==hashlib.sha256(data).hexdigest()
root=Path('rag/eval/baselines/plan_v1');m=json.loads((root/'manifest.json').read_text())
for n,h in m['file_sha256'].items(): assert hashlib.sha256((root/n).read_bytes()).hexdigest()==h,n
p=Path('/home/ubuntu/portfolio/downloads/rag/plan-v1-acceptance-2026-10-13.md');shutil.copyfile('rag/eval/reports/plan_v1_acceptance.md',p);p.chmod(0o644)
print('Synced files:',len(payload),'frozen evidence hashes:',len(m['file_sha256']))
PY
a=$(sha256sum /home/ubuntu/portfolio/downloads/rag/plan-v1-acceptance-2026-10-13.md | cut -d ' ' -f1)
b=$(curl -fsS http://52.199.126.245/downloads/rag/plan-v1-acceptance-2026-10-13.md | sha256sum | cut -d ' ' -f1)
test "$a" = "$b"
printf 'HTTP SHA256 verified: %s\n' "$a"
